 if(sacred?.sites?.calvario?.userData.vegetation)sacred.sites.calvario.userData.vegetation.visible=visible('vegetation');
 for(const id of ['berenguer','museo'])if(civic?.sites?.[id]?.userData.vegetation)civic.sites[id].userData.vegetation.visible=visible('vegetation');
 for(const id of archaeologicalVisitIds)if(archaeology?.sites?.[id]?.group.userData.vegetation)archaeology.sites[id].group.userData.vegetation.visible=visible('vegetation');
 for(const id of ['sangre','salvador'])if(sacred?.sites?.[id]?.userData.vegetation)sacred.sites[id].userData.vegetation.visible=visible('vegetation');
 for(const[item,region]of[[terrain,'sagunto'],[portTerrain,'puerto'],[coastTerrain,'coast']])if(item)item.group.visible=activeRegion===region;
 for(const[item,region]of[[portHeritage,'puerto']])if(item)item.group.visible=activeRegion===region&&visible('monuments');
 if(coastHeritage){coastHeritage.group.visible=activeRegion==='coast';for(const site of Object.values(coastHeritage.sites)){site.group.visible=visible('monuments');site.group.traverse(o=>{if(o.userData.component==='vegetacion')o.visible=visible('vegetation');});}for(const context of [coastHeritage.pantalanContext,coastHeritage.grauContext])if(context)for(const layer of [context.buildings,context.surfaces,context.details])if(layer)layer.visible=visible('city');}
 for(const[item,region]of[[city,'sagunto'],[portCity,'puerto'],[coastCity,'coast']])if(item){item.group.visible=activeRegion===region;item.buildings.visible=item.roads.visible=visible('city');item.vegetation.visible=visible('vegetation');}
 for(const context of [portHeritage?.hornoContext,portHeritage?.talleresContext,portHeritage?.museoIndustrialContext,portHeritage?.gerenciaContext,portHeritage?.casinoContext,portHeritage?.begonaContext,portHeritage?.economatoContext,portHeritage?.barrioContext,portHeritage?.sanatorioContext,coastHeritage?.pantalanContext,coastHeritage?.grauContext])if(context?.vegetation)context.vegetation.visible=visible('vegetation');
